#!/usr/bin/env python3
"""
apply_jaika_rev01.py — Demo Jaika, revision 01.

Cambios:
  R01-01  Paleta nueva (navy + verde aqua + cian) y tokens de diseno (canvas, line, ink).
  R01-02  Logo de Jaika con isotipo (version clara y oscura).
  R01-03  Componentes nuevos: ModalDialog (hoja inferior en movil), SectionCard, KpiTile, QuickLink.
  R01-04  Inicio del cliente rediseñado + seccion "Mis creditos" con "Solicitar nuevo credito".
  R01-05  Varios creditos por cliente en el store (migracion automatica de datos guardados).
  R01-06  Solicitud: si ya hay un credito preaprobado o mas adelante, ofrece pedir uno nuevo.
  R01-07  Cronograma en movil: resumen + cronograma completo en popup.
  R01-08  Minuta de compraventa disponible desde la preaprobacion (como dijo Sidney).
  R01-09  Textos de las etapas alineados con la reunion.

Uso (desde la carpeta jaika-demo):
    python apply_jaika_rev01.py src --dry-run
    python apply_jaika_rev01.py src
Si un archivo cambio desde la version revisada, NO se toca y se reporta como CONFLICTO.
Respaldo: cada archivo modificado se copia antes a .rev01-backup/.
"""
import base64, hashlib, json, shutil, sys
from pathlib import Path

PAYLOAD = json.loads(r"""[{"path": "components/credit-timeline.tsx", "orig_sha": "1dfb5fd2be503c456af1d8961fcd6e6caa970c85b7359168a97bb7e4c6cb150c", "content": ""}, {"path": "components/jaika-logo.tsx", "orig_sha": "bbddf4602d40811aac3d55f9a006944610e6eb81b757079bea0071a6f7a724f7", "content": ""}, {"path": "components/modal-dialog.tsx", "orig_sha": null, "content": ""}, {"path": "components/onboarding.tsx", "orig_sha": "9d04258293623abe85708f8d1ad57ec1bb9ea0a567c42eeec916d44068a0da37", "content": ""}, {"path": "components/portal-shell.tsx", "orig_sha": "6cd246ae7cabea9206cbfccdf983b504d0f7da67e92ac23c16b2d61ea80d547d", "content": ""}, {"path": "components/portal.tsx", "orig_sha": null, "content": ""}, {"path": "components/support-bot.tsx", "orig_sha": "bfd6cc7f763fe688af0de0b2f3eb0030e67da68b6091be5e268e2f1bb7216582", "content": ""}, {"path": "components/ui-kit.tsx", "orig_sha": null, "content": ""}, {"path": "lib/jaika-demo-store.ts", "orig_sha": "7569cbd6c442405cca7610184b7ce620e34ba92109fcdb3909920e35cc923d9f", "content": ""}, {"path": "routes/app.cronograma.tsx", "orig_sha": "cfac8c483bbdb5c0c34e92a00b866f10916ea52a855ecbec4bd61d464e0318eb", "content": ""}, {"path": "routes/app.cuenta.tsx", "orig_sha": "1e7a324b9076bbb02a7d1e822936fcdd01088723f0e933565fb85efbf4e82820", "content": ""}, {"path": "routes/app.documentos.tsx", "orig_sha": "66d45faa41ec5fb04940c1811c7d3add976ecb4a44902247ace4961f1a5c46c7", "content": ""}, {"path": "routes/app.index.tsx", "orig_sha": "4d72b1a0823772a4bf47a8a13a8dfd1cb6d5d7c8350c63f79728c152d179cb3c", "content": ""}, {"path": "routes/app.preaprobacion.tsx", "orig_sha": "2a2252a95319612a7a806d773e089d7afdb08c4e9a983d333b13c420802cd4aa", "content": ""}, {"path": "routes/app.solicitud.tsx", "orig_sha": "b53d13274464d262dd9b70adc6009b35393786005f0088c74330f7bce892c8ab", "content": ""}, {"path": "routes/index.tsx", "orig_sha": "22a12368fbf58b72100b378791ec51a027ae19594fa5634990af30235260ef05", "content": ""}, {"path": "routes/onboarding.datos-personales.tsx", "orig_sha": "5a6f5c7c3e251ecfcc7809671988ab752c2da86989636d5a79d0c16ee0926ff8", "content": ""}, {"path": "styles.css", "orig_sha": "533cc6cb7fffdb0c6aed63a6d31dbe053b28d482dcc3d833cb022d4ebe3a147d", "content": ""}]""")

def norm(b): return b.replace(b"\r\n", b"\n")

def main():
    try: sys.stdout.reconfigure(encoding="utf-8", errors="replace")
    except Exception: pass
    args = [a for a in sys.argv[1:] if not a.startswith("--")]
    dry = "--dry-run" in sys.argv
    src = Path(args[0] if args else "src").resolve()
    if not (src / "routes").is_dir():
        sys.exit(f"No encuentro {src}/routes. Ejecuta: python apply_jaika_rev01.py src")
    backup = src.parent / ".rev01-backup"
    ok = ya = conf = 0
    plan = []
    for it in PAYLOAD:
        p = src / it["path"]
        nuevo = base64.b64decode(it["content"])
        if p.exists():
            actual = p.read_bytes()
            if norm(actual) == nuevo:
                print(f"  {it['path']:48} YA APLICADO"); ya += 1; continue
            if it["orig_sha"] is None or hashlib.sha256(norm(actual)).hexdigest() != it["orig_sha"]:
                print(f"  {it['path']:48} CONFLICTO (cambio desde la version revisada)"); conf += 1; continue
            crlf = b"\r\n" in actual
        else:
            if it["orig_sha"] is not None:
                print(f"  {it['path']:48} CONFLICTO (no existe)"); conf += 1; continue
            crlf = False
        print(f"  {it['path']:48} OK"); ok += 1
        plan.append((p, nuevo.replace(b"\n", b"\r\n") if crlf else nuevo, it["path"]))
    print(f"\nRESUMEN: {ok} cambios OK, {ya} YA APLICADO, {conf} conflictos")
    if conf:
        print("Hay conflictos: no se escribio nada. Envia el src actual para regenerar la revision.")
        return
    if dry:
        print("\nDRY-RUN: verificado, no se escribio nada."); return
    for p, data, rel in plan:
        if p.exists():
            b = backup / rel; b.parent.mkdir(parents=True, exist_ok=True); shutil.copy2(p, b)
        p.parent.mkdir(parents=True, exist_ok=True)
        p.write_bytes(data)
        print(f"escrito: {rel}")
    print(f"\nListo. Respaldo en {backup}. Ahora: npm run build  y  npx tsc --noEmit")

if __name__ == "__main__":
    main()
